def main():
 pubs={p['registry_key']:p for p in L.read('publication_reviews')}
 for key,ptype,stage,rel,url,loc,note in NOTES:
  names=['batch_0011_daccad_indexed_sections.json'] if key.startswith('10.1098') else ['batch_0011_rotation_primary.json','batch_0011_rotation_more.json']
  p=pubs[key];p.update(review_stage=stage,relevance=rel,publication_type=[ptype],design_contributions=['uncertain'],catalog_eligibility='unresolved',access='partial',evidence=[evidence(L.HERE/n,url,loc) for n in names],rationale=note,unresolved_questions=['Acquire complete primary PDF/SI and trace exact reused sources or complete scope audit.','Enumerate full bibliography and reconcile conference/journal counterparts without assuming identity.'],reviewer='Codex primary article text excerpts and indexed sections; access limits explicit',run_id='B0011',date=L.DATE)
  L.upsert('publication_reviews',p,'Record rotating source review without converting access limitations to exclusions')
 for source,target,loc,relation in [
  ('10.1109/nems.2014.7031669','reference:10.1109/nems.2014.7031669:9','Materials and ref9: Kiss/Hautzinger/Tabata/Korvink AuNPs conjugate DNA origami nanotubes for nanophotonic application, NEMS2012,402–404','uses_method_from'),
  ('10.1116/1.4879417','10.1038/nchem.1070','Experiment A and ref19: Woo/Rothemund NatChem2011,3,620','reuses_design_from')]:
  ev=pubs[source]['evidence'][-1]
  L.upsert('discovery_edges',dict(edge_id='B0011-parent:'+source,source_key=source,target_key=target,relation=relation,evidence_url=ev['url'],local_file=ev['local_file'],sha256=ev['sha256'],locator=loc,reconciliation_state='pending_exact_variant_and_primary_identity' if source.startswith('10.1109') else 'bibliographic_parent_matched; exact_variant_pending',run_id='B0011',date=L.DATE),'Retain explicit preparation/design attribution; source composition still unresolved')
 b=next(b for b in L.read('batches') if b['batch_id']=='B0011')
 action='Reviewed3rotating records: nanotube conference reuse, thermal rectangle reuse, and uncertain DACCAD scope under partial access;19/25first passes.'
 if action not in b['completed_actions']:b['completed_actions'].append(action)
 b.update(after_counts=L.counts(),validation=[L.validate()],next_queue=['Review6remaining rotating B0011records','Trace Kiss2012 and Woo2011 exact design sources; complete DACCAD scope audit','FNANO2012/abstracts, forward citations and author histories remain open'])
 L.upsert('batches',b,'Checkpoint19/25; no new exclusion')
 L.atomic(L.HERE/'batch_0011_rotation_first_audit.json',json.dumps(dict(batch_id='B0011',first_pass_count=19,input_count=25,validation=L.validate(),counts=L.counts()),indent=2)+'\n')
 print(L.validate())
if __name__=='__main__':main()
